// Step 1: Create the context
const ThemeContext = createContext('light');  // default value if no Provider above

// Step 2: Create a Provider component (good pattern: keep state + context together)
function ThemeProvider({ children }) {
    const [theme, setTheme] = useState('light');
    return (
        <ThemeContext.Provider value={{ theme, setTheme }}>
            {children}
        </ThemeContext.Provider>
    );
}

// Custom hook for convenience
function useTheme() {
    return useContext(ThemeContext);
}

// Step 3: Consume anywhere in the tree — no props needed!
function ThemeToggle() {
    const { theme, setTheme } = useTheme();
    return (
        <button onClick={() => setTheme(t => t === 'light' ? 'dark' : 'light')}>
            {theme === 'light' ? '🌙 Dark Mode' : '☀️ Light Mode'}
        </button>
    );
}

function Page() {
    const { theme } = useTheme();
    const isDark = theme === 'dark';
    return (
        <div style={{
            background: isDark ? '#0e1116' : '#fff',
            color: isDark ? '#e2e8f0' : '#111',
            padding: '16px', borderRadius: '8px', transition: 'all 0.3s'
        }}>
            <h2>Theme: {theme}</h2>
            <p>This page reads the theme from context.</p>
            <ThemeToggle />
        </div>
    );
}

function App() {
    return (
        <ThemeProvider>
            <Page />  {/* Page and all its children can access ThemeContext */}
        </ThemeProvider>
    );
}
